INSERT INTO ui.dashboardquery (
idashboardqueryid, bparametersrequired, vcfilterparametersjson, vcdashboardquery, formattingrequiered, runonanalytics, transposerequired, imenustructuredesc, itenantid) VALUES (
'145'::integer, true::boolean, '{"placeholders": null, "workflowkey": null}'::text,  E'SELECT proinst.business_key_ AS \\"txnid\\", proinst.id_ AS \\"processid\\", task.task_def_key_ AS \\"taskdefkey\\", task.id_ AS \\"taskid\\", ticketid.long_ AS \\"ticketid\\" FROM camunda.act_hi_procinst proinst INNER JOIN camunda.act_ru_task task ON task.proc_inst_id_ = proinst.id_ INNER JOIN camunda.act_ru_variable ticketid ON ticketid.proc_inst_id_ = proinst.id_ AND ticketid.name_ = ''TicketID'' WHERE proinst.business_key_ IN (:placeholders) AND proinst.state_ = ''ACTIVE'' AND proinst.proc_def_key_ = :workflowkey;
'::text, false::boolean, false::boolean, false::boolean, '479'::integer, '10'::integer);

