 UPDATE ui.dashboardquery SET
 vcdashboardquery = 'SELECT proinst.business_key_ AS txnid, proinst.id_ AS processid, task.task_def_key_ AS taskdefkey, task.id_ AS taskid, ticketid.long_ AS ticketid FROM camunda.act_hi_procinst proinst INNER JOIN camunda.act_ru_task task ON task.proc_inst_id_ = proinst.id_ INNER JOIN camunda.act_ru_variable ticketid ON ticketid.proc_inst_id_ = proinst.id_ AND ticketid.name_ = ''TicketID'' WHERE proinst.business_key_ IN (:placeholders) AND proinst.state_ = ''ACTIVE'' AND proinst.proc_def_key_ = :workflowkey;'::text WHERE
 idashboardqueryid = 145 AND itenantid = 10;

 UPDATE ui.dashboardqueryparameters SET
 vcparametertype = 'List<String>'::character varying WHERE
 idashboardparameterid = 292 AND itenantid = 10;